#[derive(Debug, PartialEq)]
struct Setting {
    key: String,
    value: i64,
}

#[derive(Debug, PartialEq)]
enum ParseError {
    MissingEquals,
}

fn parse_line(line: &str) -> Result<Setting, ParseError> {
    Err(ParseError::MissingEquals)
}

fn main() {
    for line in ["width=800", "width", "=800", "width=wide"] {
        println!("{line:?} -> {:?}", parse_line(line));
    }
}
